import{_ as i,c as l,o as e,a3 as r}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"プライバシーポリシー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy.md","filePath":"ja/guide/privacy.md","lastUpdated":1787284674000}'),t={name:"ja/guide/privacy.md"};function o(n,a,s,h,c,d){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><p>ClipboxAI は macOS 向けのスマートなクリップボードマネージャーです。お客様のプライバシーを最優先に考えています。</p><h2 id="ローカルファーストの設計" tabindex="-1">ローカルファーストの設計 <a class="header-anchor" href="#ローカルファーストの設計" aria-label="Permalink to &quot;ローカルファーストの設計&quot;">​</a></h2><ul><li>クリップボードの履歴は、お客様の Mac 上のみに保存されます。</li><li>内蔵のローカルアクション（リンク抽出、集計、空白行削除、および端末上の ML による提案）は完全にオフラインで動作します。</li><li>コアアプリを利用するためにアカウントや登録は不要です。</li><li>ローカルのクリップボード管理や端末上の機能にはインターネット接続は不要です。</li></ul><h2 id="クラウド-ai-任意" tabindex="-1">クラウド AI（任意） <a class="header-anchor" href="#クラウド-ai-任意" aria-label="Permalink to &quot;クラウド AI（任意）&quot;">​</a></h2><p>ClipboxAI は、任意でクラウド AI プロバイダー（DeepSeek、MiniMax、GLM、Kimi、Mistral、またはローカルの Ollama サーバーなど）を使用し、要約・翻訳・カスタムプロンプトなどの高度なアクションを実現できます。</p><ul><li>有効にした場合、選択したテキストやクリップボードの内容は、<strong>ご自身で設定したプロバイダーに直接</strong>、<strong>ご自身の API key</strong> を使って送信されます。</li><li>API key はお客様の Mac の Keychain にのみ保存され、私たちへアップロードされることはありません。</li><li>クラウド AI はいつでも無効にでき、その後もローカル機能を引き続き利用できます。</li><li>クリップボード履歴が自動的にクラウドへ送信されることは<strong>ありません</strong>。クラウドへのリクエストは、クラウドアクションを実行したときにのみ発生します。</li></ul><h2 id="私たちが収集しないもの" tabindex="-1">私たちが収集しないもの <a class="header-anchor" href="#私たちが収集しないもの" aria-label="Permalink to &quot;私たちが収集しないもの&quot;">​</a></h2><ul><li>クリップボードの内容、ドキュメント、ファイルを収集しません。</li><li>お客様のアクティビティ、閲覧行動、利用パターンを追跡しません。</li><li>お客様のクリップボードデータを受信するサーバーを運用していません。</li><li>サードパーティのアナリティクス・広告・追跡用 SDK を含みません。</li><li>テレメトリシステムは一切存在しません。</li></ul><h2 id="ローカルに保存されるデータ" tabindex="-1">ローカルに保存されるデータ <a class="header-anchor" href="#ローカルに保存されるデータ" aria-label="Permalink to &quot;ローカルに保存されるデータ&quot;">​</a></h2><p>以下のデータはお客様のデバイスのみに保存されます。</p><ul><li><strong>クリップボード履歴</strong>: すばやくアクセスするための最近の項目（Mac 上に保持）。</li><li><strong>アプリ設定</strong>: テーマ、言語の設定、有効なアクション、プロバイダーの設定。</li><li><strong>API key</strong>: ローカルの Keychain に安全に保存（クラウドプロバイダーを設定した場合のみ）。</li><li><strong>カスタムアクション</strong>: お客様が作成したプロンプトと設定。</li><li><strong>ログ</strong>: トラブルシューティング用のデバッグログ（いつでも削除可能）。</li></ul><h2 id="アプリが使用する権限" tabindex="-1">アプリが使用する権限 <a class="header-anchor" href="#アプリが使用する権限" aria-label="Permalink to &quot;アプリが使用する権限&quot;">​</a></h2><ul><li><strong>アクセシビリティ / フルディスクアクセス</strong>: システムのクリップボードの読み取りとグローバルショートカットの提供に必要。</li><li><strong>通知</strong>: 時間のかかるクラウドリクエストの完了通知用（任意）。</li></ul><p>これらの権限はいつでも <strong>システム設定 → プライバシーとセキュリティ</strong> で管理できます。</p><h2 id="アプリ内課金-ライセンス" tabindex="-1">アプリ内課金 / ライセンス <a class="header-anchor" href="#アプリ内課金-ライセンス" aria-label="Permalink to &quot;アプリ内課金 / ライセンス&quot;">​</a></h2><p>ライセンスの購入（ある場合）は、Apple を通じて Mac App Store 経由で処理されます。ClipboxAI がお客様の決済情報を受け取ったり保存したりすることはありません。ライセンスのレシートは、所有権の確認のためローカルに保存されます。</p><h2 id="サードパーティサービス" tabindex="-1">サードパーティサービス <a class="header-anchor" href="#サードパーティサービス" aria-label="Permalink to &quot;サードパーティサービス&quot;">​</a></h2><p>ClipboxAI 自体にはサードパーティのアナリティクス・広告・追跡サービスは含まれていません。クラウド AI プロバイダーを有効にした場合、お客様のリクエストはそのプロバイダー自身のプライバシーポリシーに基づいて処理されます。</p><h2 id="プライバシーに関するご要望" tabindex="-1">プライバシーに関するご要望 <a class="header-anchor" href="#プライバシーに関するご要望" aria-label="Permalink to &quot;プライバシーに関するご要望&quot;">​</a></h2><p>ClipboxAI はすべてのデータをお客様のデバイスにローカルに保存するため、私たちのサーバー上に個人データを保持していません。プライバシーについてご質問がある場合は、お問い合わせください。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>プライバシーに関するご質問は、<a href="https://github.com/clipboxAI/clipboard-site/issues" target="_blank" rel="noreferrer">GitHub Issues</a> で issue を作成するか、clipboxai@w3cub.com までメールでお寄せください。</p>',23)])])}const b=i(t,[["render",o]]);export{u as __pageData,b as default};
